static void advance_buffer(aac_buffer *b, int bytes) /* <=== advance_buffer */ 
{
    b->file_offset += bytes;
    b->bytes_consumed = bytes;
    b->bytes_into_buffer -= bytes;
	if (b->bytes_into_buffer < 0)
